<template>
  <div>
    <h2 class="my-4">
      所有評論：
    </h2>

    <div v-for="comment in restaurantComments" :key="comment.id">
      <blockquote class="blockquote mb-0">
        <button v-if="currentUser.isAdmin" @click.stop.prevent="handlerDeleteButtonClick(comment.id)" type="button"
          class="btn btn-danger float-right" :disabled="comment.id === deletingId">
          {{ deletingId === comment.id ? '處理中...' : 'Delete'}}
        </button>
        <h3>
          <router-link :to="{ name: 'user', params: { id: comment.User.id } }">
            {{ comment.User.name }}
          </router-link>
        </h3>
        <p>{{ comment.text }}</p>
        <footer class="blockquote-footer">
          {{ comment.createdAt | fromNow }}
        </footer>
      </blockquote>
      <hr>
    </div>
  </div>
</template>

<script>
import { fromNowFilter } from '../utils/mixins'

const dummyUser = {
  currentUser: {
    id: 1,
    name: '管理者',
    email: 'root@example.com',
    image: 'https://i.pravatar.cc/300',
    isAdmin: true
  },
  isAuthenticated: true
}

export default {
  mixins: [fromNowFilter],
  name: 'RestaurantComments',
  props: {
    restaurantComments: {
      type: Array,
      required: true
    },
    deletingId: {
      type: Number,
      default: null
    },
  },
  data() {
    return {
      currentUser: dummyUser.currentUser
    }
  },
  methods: {
    handlerDeleteButtonClick(commentId) {
      // TODO: 打 api 刪除 comment REVIEW: FIXME: NOTE:
      this.$emit('after-delete-comment', commentId)
    }
  }
}
</script>
<style scoped>
h2.my-4 {
  margin-bottom: 1rem !important;
  font-size: 18px;
}

h3 {
  margin-bottom: 3px;
  line-height: 1.3;
}

.blockquote-footer {
  font-size: 12.5px;
}
</style>